export class Fullscreen{constructor(){this.initialized=!1}init(){if(this.initialized)return;const e=document.querySelector(".fullscreen-menu");if(!e)return;const t=document.querySelector(".fm-toggle"),l=document.querySelector(".fm-close");t&&t.addEventListener("click",()=>{e.classList.toggle("fm-show")}),l&&l.addEventListener("click",()=>{e.classList.remove("fm-show"),t&&t.classList.remove("fm-toggle-hide")}),this.initialized=!0,console.log("✅ Fullscreen menu initialized")}}export const FullscreenMenu=Fullscreen;export default Fullscreen;